let stored={};try{stored=JSON.parse(localStorage.getItem('huisheng-v1')||'{}')}catch{}let posts=stored.posts||initial,joined=stored.joined||['tech','design'],saved=stored.saved||[],votes=stored.votes||{},view='all',sort='recommended',query='';const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const community=id=>communities.find(c=>c.id===id),icon=c=>`<span class="community-icon" style="--bg:${c.color}">${c.icon}</span>`;function persist(){try{localStorage.setItem('huisheng-v1',JSON.stringify({posts,joined,saved,votes}))}catch{toast('浏览器存储不可用，本次更改仅在当前页面保留')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function renderFeed(){ $('#communities').innerHTML=communities.map(c=>`<button class="community ${view===c.id?'active':''}" data-view="${c.id}">${icon(c)}${c.name}</button>`).join('');$('#recommendations').innerHTML=communities.slice(0,4).map(c=>`<div class="rec">${icon(c)}<button class="rec-name" data-view="${c.id}"><strong>${c.name}</strong><small>${c.members} 位同好</small></button><button class="join" data-join="${c.id}">${joined.includes(c.id)?'已加入':'+ 加入'}</button></div>`).join('');document.querySelectorAll('.nav-main button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('[data-sort]').forEach(b=>b.classList.toggle('active',b.dataset.sort===sort));const c=community(view);$('#feedTitle').textContent=query?'搜索结果':c?c.name:({all:'为你发现',hot:'热门讨论',joined:'我的社区',saved:'我的收藏'}[view]);$('#feedSub').textContent=c?'找到同频的人，分享你的热爱。':view==='saved'?'把值得回看的想法留在这里。':'有趣的事，值得一起聊。';$('.hero').hidden=view!=='all'||!!query;let list=posts.filter(p=>(view==='all'||view==='hot'||view==='saved'&&saved.includes(p.id)||view==='joined'&&joined.includes(p.c)||p.c===view)&&(!query||(p.title+p.body+community(p.c).name).toLowerCase().includes(query.toLowerCase())));if(sort==='top'||view==='hot')list.sort((a,b)=>(b.votes+(votes[b.id]||0))-(a.votes+(votes[a.id]||0)));if(sort==='new')list.sort((a,b)=>b.createdAt-a.createdAt);$('#resultCount').textContent=list.length+' 篇讨论';$('#feed').innerHTML=list.map(p=>{const c=community(p.c);return `<article class="post">${postAuthorHeader(p)}<button class="post-title" data-post="${p.id}">${esc(p.title)}</button><p>${esc(p.body.slice(0,120))}${p.body.length>120?'…':''}</p><span class="tag">${esc(p.tag)}</span>${p.image?`<img class="post-image" src="${p.image}" alt="${p.c==='design'?'自然光下的工作空间':'山间云雾与自然风景'}" loading="lazy">`:''}${imageGallery(p.images)}<div class="actions">${postLikeButton(p)}<button data-feed-toggle="${p.id}" data-feed-count="${p.id}">☏ ${commentCount(p.comments)} 条讨论</button><button data-share="${p.id}">↗ 分享</button><button class="save ${saved.includes(p.id)?'selected':''}" data-save="${p.id}">${saved.includes(p.id)?'▰ 已收藏':'▱ 收藏'}</button></div>${feedComments(p)}</article>`}).join('')||'<div class="empty">这里暂时没有讨论。<br><br>换个关键词，或发布你的第一个想法。</div>'}
const modal=$('#modal');function open(html){$('#modalBody').innerHTML=html;if(!modal.open)modal.showModal()}
function composeBase(){open(`<div class="mini-label">START A CONVERSATION</div><h2>分享你的一个想法</h2><form id="postForm"><label>发布到哪个社区<select name="community">${communities.map(c=>`<option value="${c.id}" ${view===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label>标题<input name="title" required maxlength="100" placeholder="一个好标题，是讨论的开始"></label><label>正文<textarea name="body" required maxlength="10000" placeholder="说说你的发现、问题，或故事…"></textarea></label><p>友善交流，尊重不同观点。体验版帖子保存在当前浏览器。</p><button class="primary">发布帖子 ↗</button></form>`);$('#postForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),body=f.get('body').trim();if(!title||!body)return;posts.unshift({id:Date.now(),c:f.get('community'),user:'我',time:'刚刚',createdAt:Date.now(),title,body,tag:'新鲜想法',votes:1,comments:[],count:0});leaveDetail(false);view='all';query='';$('#search').value='';sort='new';persist();render();modal.close();toast('帖子已发布，保存在当前浏览器')}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.view){leaveDetail(false);view=d.view;query='';$('#search').value='';render()}if(d.sort){sort=d.sort;render()}if(d.join){joined=joined.includes(d.join)?joined.filter(c=>c!==d.join):[...joined,d.join];persist();render();if(modal.open&&$('#discovery'))discover()}if(d.post)showPost(+d.post);if(d.save){const id=+d.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render()}if(d.vote){const id=+d.vote;votes[id]=votes[id]===+d.dir?0:+d.dir;persist();render()}if(d.share){const url=location.origin+location.pathname+'#post-'+d.share;try{await navigator.clipboard.writeText(url);toast('帖子链接已复制；自建帖子仅在本机可见')}catch{open(`<h2>分享讨论</h2><input aria-label="帖子链接" readonly value="${esc(url)}"><p>复制以上链接。自建帖子仅保存在当前浏览器。</p>`)}}if(d.query){leaveDetail(false);query=d.query;view='all';$('#search').value=query;render()}if(d.action==='compose')compose();if(d.action==='discover')discover();if(d.action==='profile')showProfile('我')});function discover(){open(`<div id="discovery"><div class="mini-label">FIND YOUR PEOPLE</div><h2>找到属于你的兴趣角落</h2>${communities.map(c=>`<div class="rec">${icon(c)}<div><strong>${c.name}</strong><small>${c.members} 位同好 · 示例社区</small></div><button class="join" data-join="${c.id}">${joined.includes(c.id)?'已加入':'+ 加入社区'}</button></div>`).join('')}</div>`)}$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});$('#search').addEventListener('input',e=>{leaveDetail(false);query=e.target.value;render()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!modal.open){e.preventDefault();$('#search').focus()}});

