const migrationNow=Date.now();
function normalizeComments(items,base){return (Array.isArray(items)?items:[]).map((c,i)=>({...c,id:c.id||crypto.randomUUID(),createdAt:c.createdAt||base+i*60000,likes:c.likes||0,replies:normalizeComments(c.replies,base+i*60000)}))}
posts=posts.map(p=>({...p,createdAt:p.createdAt||(p.id>1000000000000?p.id:migrationNow-(p.id+1)*3600000),comments:normalizeComments(p.comments,p.createdAt||migrationNow-3600000)}));
function commentCount(items){return items.reduce((n,c)=>n+1+commentCount(c.replies||[]),0)}
function relativeTime(t){const mins=Math.max(0,Math.floor((Date.now()-t)/60000));return mins<1?'刚刚':mins<60?mins+' 分钟前':mins<1440?Math.floor(mins/60)+' 小时前':new Date(t).toLocaleDateString('zh-CN')}
