function leaveDetailBase(){if(activePost!==null||activeProfile!==null||activeLearning!==null||activeMini!==null){rememberDraft();activeMini=null;activeLearning=null;activeProfile=null;activePost=null;detail.innerHTML='';document.title='回声 · 兴趣相投，自有回响';history.pushState(null,'',location.pathname+location.search)}}
function rememberDraft(){const box=$('#replyText');if(box&&activePost!==null)drafts.set(activePost+':'+(replyTarget||'root'),box.value)}
function renderBase(){renderFeed();const isDetail=activePost!==null||activeProfile!==null||activeLearning!==null||activeMini!==null;main.classList.toggle('reading',isDetail);detail.hidden=!isDetail;if(activeMini!==null)renderMini();else if(activeLearning!==null)renderLearning();else if(activeProfile!==null)renderProfile();else if(isDetail)renderDetail();document.querySelectorAll('.mobile-nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view&&!isDetail))}
