let activeLearning=null,courseFilter='all';
function saveLearning(){try{localStorage.setItem('echo-learning',JSON.stringify(learningState));return true}catch{toast('学习进度保存失败');return false}}
function lessonAccessible(index){return index<2}
function courseProgress(c){return (learningState.completed[c.id]||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<c.lessons.length).length}
function openLearning(id='catalog',lesson){captureReading();activeMini=null;activePost=null;activeProfile=null;replyTarget=null;activeLearning=id;detail.innerHTML='';const c=courseCatalog.find(c=>c.id===id);if(c){learningState.lastLesson[id]=lesson!==undefined?lesson:(learningState.lastLesson[id]||0);saveLearning()}const hash=id==='catalog'?'#courses':'#course-'+id;history.pushState(null,'',hash);currentReadingKey=hash;render();window.scrollTo({top:0,behavior:'instant'})}
function renderLearningBase(){if(activeLearning==='catalog'){document.title='学习课堂 · 回声';const list=courseCatalog.filter(c=>courseFilter==='all'||c.category===courseFilter);detail.innerHTML=`<section class="learning-hero photo-hero"><img class="learning-hero-photo" src="${COURSE_PHOTOS['ai-work']}" alt=""><div class="eyebrow">ECHO ACADEMY</div><h1>把好奇，变成会做。</h1><p>从 AI 到财经与生活，每次学一点，慢慢走得更远。</p><div class="learning-hero-actions"><span>每门课程前 2 节免费试看</span><button class="primary" data-membership>查看会员方案</button></div></section><div class="learning-label">精选课程 · 按自己的节奏学习</div><div class="course-filters">${[['all','全部课程'],['ai','AI 教学'],['finance','财经基础'],['life','生活技能']].map(([key,label])=>`<button data-course-filter="${key}" aria-pressed="${courseFilter===key}">${label}</button>`).join('')}</div><div class="course-grid">${list.map(c=>`<article class="course-card"><button class="course-art ${c.color}" data-course="${c.id}" aria-label="查看课程：${esc(c.title)}"><img class="course-cover-photo" src="${COURSE_PHOTOS[c.id]}" alt="${COURSE_PHOTO_ALTS[c.id]}" loading="lazy"><span class="course-cover-tag">${c.category==='ai'?'AI 教学':c.category==='finance'?'财经基础':'生活技能'}</span><small>回声课堂 / ${c.level}</small></button><div class="course-card-body"><div class="course-caption">${c.lessons.length} 节图文课 · 2 节免费</div><button class="course-title" data-course="${c.id}">${c.title}</button><p>${c.subtitle}</p>${authorLink(c.teacher)}<div class="course-progress"><progress max="${c.lessons.length}" value="${courseProgress(c)}" aria-label="学习进度"></progress><span>${courseProgress(c)}/${c.lessons.length}</span></div><button class="course-start" data-course="${c.id}">${courseProgress(c)?'继续学习 →':'免费开始 →'}</button></div></article>`).join('')}</div>`;return}const c=courseCatalog.find(c=>c.id===activeLearning);if(!c){detail.innerHTML='<h2>课程不存在</h2><button data-course="catalog">返回课堂</button>';return}document.title=c.title+' · 回声课堂';const index=Math.max(0,Math.min(c.lessons.length-1,Number(learningState.lastLesson[c.id])||0)),lesson=c.lessons[index],unlocked=lessonAccessible(index),done=(learningState.completed[c.id]||[]).includes(index);detail.innerHTML=`<button class="back-link" data-course="catalog">← 返回课堂</button><section class="course-overview"><figure class="course-detail-photo"><img src="${COURSE_PHOTOS[c.id]}" alt="${COURSE_PHOTO_ALTS[c.id]}"><figcaption>课程主题配图</figcaption></figure><span class="mini-label">${c.level} · ${c.lessons.length} 节图文课</span><h1>${c.title}</h1><p>${c.subtitle}</p>${authorLink(c.teacher)}<div class="learning-label">循序渐进 · 学习与练习相结合</div></section><div class="course-workspace"><nav class="lesson-list" aria-label="课程目录"><h3>课程目录</h3>${c.lessons.map((l,i)=>`<button data-lesson="${i}" data-course-id="${c.id}" aria-current="${index===i?'step':'false'}"><span class="lesson-number">${(learningState.completed[c.id]||[]).includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${l[0]}<small>${i<2?'Starter 免费试看':c.level==='实践'?'Pro 会员':'Beginner / Pro'}</small></span><span>${lessonAccessible(i)?'':'🔒'}</span></button>`).join('')}<small class="lesson-progress">已完成 ${courseProgress(c)} / ${c.lessons.length} 节</small></nav><article class="lesson-content"><div class="lesson-eyebrow">LESSON ${String(index+1).padStart(2,'0')} <span>${index<2?'Starter 免费试看':c.level==='实践'?'Pro 会员课程':'Beginner / Pro 会员课程'}</span></div><h2>${lesson[0]}</h2>${unlocked?`<p class="lesson-copy">${lesson[1]}</p><section class="lesson-practice"><h3>动手练习</h3><p>${lesson[2]}</p></section>${c.category==='finance'?'<p class="learning-label">本课程仅介绍基础概念，不提供个性化投资建议。</p>':''}<div class="lesson-controls"><button class="primary" data-complete-lesson="${index}" data-course-id="${c.id}" aria-pressed="${done}">${done?'✓ 已完成，点击撤销':'标记本节完成'}</button>${index<c.lessons.length-1?`<button data-lesson="${index+1}" data-course-id="${c.id}">下一节 →</button>`:'<button data-course="catalog">返回课程列表 →</button>'}</div>`:`<div class="lesson-locked"><span class="lock-art">▣</span><h3>继续学习，解锁完整课程</h3><p>前两节免费试看。入门课程包含于 Beginner 与 Pro，实践课程包含于 Pro。</p><button class="primary" data-membership>查看订阅方案</button><button class="free-lesson-link" data-lesson="0" data-course-id="${c.id}">先看免费内容</button></div>`}</article></div>`}
