function showMembership(){modal.classList.add('plans-dialog');open(`<div class="plans-heading"><div class="mini-label">ECHO MEMBERSHIP</div><h2>选择适合你的学习方式</h2><p>从免费探索，到系统学习，再到深入实践。</p><span class="billing-label">按月订阅 · MYR 马来西亚令吉</span></div><div class="pricing-grid">${membershipPlans.map(p=>`<section class="pricing-card ${p.id==='beginner'?'recommended-plan':''}">${p.id==='beginner'?'<div class="plan-ribbon">推荐方案</div>':''}<div class="plan-name">${p.name}</div><p class="plan-caption">${p.caption}</p><div class="plan-price"><span>RM</span> ${p.price}<small>${p.price?'/ 月':'/ 免费'}</small></div><p class="plan-audience">${p.note}</p><button class="${p.id==='beginner'?'primary':'plan-choice'}" data-select-plan="${p.id}">${p.cta}</button><ul>${p.features.map(f=>`<li><span>✓</span>${f}</li>`).join('')}</ul></section>`).join('')}</div><div class="plans-comparison"><h3>一眼看懂方案差异</h3><div class="comparison-scroll"><table><thead><tr><th>学习权益</th><th>Starter</th><th>Beginner</th><th>Pro</th></tr></thead><tbody><tr><td>社区交流、收藏与学习进度</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>课程免费试看</td><td>每门前 2 节</td><td>✓</td><td>✓</td></tr><tr><td>完整入门课程与练习</td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>实践课程与项目练习</td><td>—</td><td>—</td><td>✓</td></tr></tbody></table></div></div><p class="plans-payment-note">付费订阅即将开放。你现在可以免费学习 Starter 内容。</p>`)}
function selectMembershipPlan(id){const p=membershipPlans.find(p=>p.id===id);if(!p)return;if(id==='starter'){modal.close();openLearning('catalog');return}open(`<div class="mini-label">YOUR MEMBERSHIP</div><h2>${p.name} 订阅</h2><div class="plan-order-summary"><span>${p.name} · 按月订阅</span><strong>RM ${p.price}<small> / 月</small></strong></div><h3>订阅后可享</h3><ul class="plan-order-benefits">${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><div class="payment-unavailable"><strong>支付服务尚未开放</strong><p>暂时无法购买或开通付费会员，不会产生扣费。你仍可免费阅读每门课程的前两节。</p></div><button class="primary" disabled>暂未开放购买</button><button class="plan-back" data-membership>← 返回方案</button>`);modal.classList.remove('plans-dialog')}
modal.addEventListener('close',()=>modal.classList.remove('plans-dialog'));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.selectPlan)selectMembershipPlan(b.dataset.selectPlan)});

document.querySelector('.nav-main').insertAdjacentHTML('beforeend','<button data-course="catalog">▤ <span>学习课堂</span></button>');
const mobileExplore=document.querySelector('.mobile-nav [data-action="discover"]');if(mobileExplore){const shortcut=document.createElement('button');shortcut.dataset.course='catalog';shortcut.innerHTML='▤<span>课堂</span>';mobileExplore.insertAdjacentElement('afterend',shortcut)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.course)openLearning(d.course);if(d.courseFilter){courseFilter=d.courseFilter;renderLearning()}if('lesson'in d){const c=courseCatalog.find(c=>c.id===d.courseId),index=Number(d.lesson);if(!c||!Number.isInteger(index)||index<0||index>=c.lessons.length)return;learningState.lastLesson[c.id]=index;saveLearning();renderLearning();detail.querySelector('.lesson-content')?.scrollIntoView({behavior:'smooth',block:'start'})}if('membership'in d)showMembership();if('completeLesson'in d){const c=courseCatalog.find(c=>c.id===d.courseId),index=Number(d.completeLesson);if(!c||!Number.isInteger(index)||index<0||index>=c.lessons.length||!lessonAccessible(index))return;const done=learningState.completed[c.id]||[];learningState.completed[c.id]=done.includes(index)?done.filter(i=>i!==index):[...done,index];saveLearning();renderLearning()}});

const miniApps=[
 {id:'schedule',name:'每日课表',tag:'学习安排',description:'把上课时间、地点和课程放在一张清楚的日程表里。',icon:'calendar',color:'blue',fields:[['title','课程名称','text',true],['weekday','每周哪一天','select',true,['周一','周二','周三','周四','周五','周六','周日']],['time','开始时间','time',true],['end','结束时间','time',true],['location','教室 / 地点','text'],['notes','备注','textarea']]},
 {id:'meals',name:'饮食记录',tag:'日常生活',description:'记录今天吃了什么，给忙碌的一天留一点生活痕迹。',icon:'meal',color:'green',fields:[['date','日期','date',true],['meal','餐次','select',true,['早餐','午餐','晚餐','加餐']],['title','吃了什么','text',true],['notes','份量 / 感受','textarea']]},
 {id:'travel',name:'旅行行程',tag:'出行计划',description:'按日期整理交通、住宿和想去的地方，出发前心里有数。',icon:'plane',color:'cyan',fields:[['trip','旅行名称','text',true],['date','日期','date',true],['time','时间','time'],['title','行程安排','text',true],['location','地点 / 地址','text'],['type','类型','select',true,['游览','交通','住宿','餐饮','其他']],['notes','预订信息 / 备注','textarea']]},
 {id:'tasks',name:'日常待办',tag:'效率工具',description:'把要做的事写下来，一件一件完成，轻松整理优先级。',icon:'check',color:'blue',fields:[['title','待办事项','text',true],['date','截止日期','date'],['priority','优先级','select',true,['普通','重要','紧急']],['notes','补充说明','textarea']]},
 {id:'habits',name:'习惯打卡',tag:'每日坚持',description:'读书、散步、早睡，每天留下一次小小的完成记录。',icon:'spark',color:'amber',fields:[['title','习惯名称','text',true],['notes','给自己的提醒','textarea']]},
 {id:'expenses',name:'日常记账',tag:'生活账本',description:'记录每笔日常支出，按月查看金额和分类汇总。',icon:'wallet',color:'green',fields:[['date','日期','date',true],['title','支出名称','text',true],['amount','金额（RM）','number',true],['category','分类','select',true,['餐饮','交通','购物','居住','学习','旅行','其他']],['notes','备注','textarea']]}
];
function miniIcon(type){const paths={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18M7 15h3m4 0h3"/>',meal:'<path d="M5 3v7m3-7v7m3-7v7M5 8h6M8 10v11M19 3c-4 3-4 9 0 9V3Zm0 9v9"/>',plane:'<path d="m21 3-7 18-4-7-7-4L21 3ZM10 14l11-11"/>',check:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="m7 12 3 3 7-7"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',wallet:'<rect x="3" y="6" width="18" height="14" rx="3"/><path d="M3 7V5a2 2 0 0 1 2-2h12v3M21 11h-6v5h6"/><circle cx="17" cy="13.5" r=".5"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[type]||paths.check}</svg>`}
function todayLocal(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-')}
let miniData={};try{miniData=JSON.parse(localStorage.getItem('echo-miniapps')||'{}')}catch{}for(const app of miniApps)if(!Array.isArray(miniData[app.id]))miniData[app.id]=[];
let activeMini=null,miniDate=todayLocal(),miniMonth=miniDate.slice(0,7),miniTrip='all',miniTaskFilter='all',miniUndo=null;
function saveMini(){try{localStorage.setItem('echo-miniapps',JSON.stringify(miniData));return true}catch{toast('保存失败，请检查浏览器存储空间');return false}}
function openMini(id='catalog'){captureReading();activeLearning=null;activeProfile=null;activePost=null;replyTarget=null;activeMini=id;detail.innerHTML='';const hash=id==='catalog'?'#apps':'#app-'+id;history.pushState(null,'',hash);currentReadingKey=hash;render();window.scrollTo({top:0,behavior:'instant'})}
function miniWeekday(date){return ['周日','周一','周二','周三','周四','周五','周六'][new Date(date+'T12:00:00Z').getUTCDay()]}
function miniVisible(app){let rows=miniData[app.id];if(app.id==='schedule')rows=rows.filter(r=>r.weekday===miniWeekday(miniDate));if(app.id==='meals')rows=rows.filter(r=>r.date===miniDate);if(app.id==='expenses')rows=rows.filter(r=>r.date.startsWith(miniMonth));if(app.id==='travel'&&miniTrip!=='all')rows=rows.filter(r=>r.trip===miniTrip);if(app.id==='tasks'&&miniTaskFilter!=='all')rows=rows.filter(r=>miniTaskFilter==='done'?r.done:!r.done);return [...rows].sort((a,b)=>app.id==='schedule'?(a.time||'').localeCompare(b.time||''):app.id==='habits'?a.createdAt-b.createdAt:app.id==='tasks'?Number(a.done)-Number(b.done)||(a.date||'9999').localeCompare(b.date||'9999'):(a.date||'').localeCompare(b.date||'')||(a.time||'').localeCompare(b.time||''))}
function money(value){return Number(value).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}
function miniRow(app,r){const checked=app.id==='habits'?(r.checks||[]).includes(miniDate):!!r.done;const toggle=['tasks','habits'].includes(app.id);const overlap=app.id==='schedule'&&miniData.schedule.some(other=>other.id!==r.id&&other.weekday===r.weekday&&other.time<r.end&&other.end>r.time);return `<article class="mini-record ${checked&&toggle?'is-complete':''}"><div class="mini-record-top">${toggle?`<button class="mini-check" data-mini-toggle="${r.id}" aria-pressed="${checked}" aria-label="${checked?'取消完成':'标记完成'}">${checked?'✓':'○'}</button>`:''}<div class="mini-record-main"><div class="mini-record-meta">${app.id==='schedule'?`${esc(r.time)} – ${esc(r.end)} · ${esc(r.weekday)}`:app.id==='habits'?`累计打卡 ${(r.checks||[]).length} 天`:app.id==='meals'?`${esc(r.date)} · ${esc(r.meal)}`:app.id==='travel'?`${esc(r.trip)} · ${esc(r.date)} ${esc(r.time||'')} · ${esc(r.type)}`:app.id==='expenses'?`${esc(r.date)} · ${esc(r.category)}`:`${r.date?esc(r.date):'无截止日期'} · ${esc(r.priority)}`}</div><h3>${esc(r.title)}</h3>${r.location?`<div class="mini-location">${esc(r.location)}</div>`:''}${overlap?'<span class="mini-conflict">与另一门课程时间重叠</span>':''}${app.id==='tasks'&&!r.done&&r.date&&r.date<todayLocal()?'<span class="mini-conflict">已过截止日期</span>':''}</div>${app.id==='expenses'?`<strong class="mini-amount">RM ${money(r.amount)}</strong>`:''}</div>${r.notes?`<p class="mini-record-note">${esc(r.notes)}</p>`:''}<div class="mini-record-actions"><button data-mini-edit="${r.id}">编辑</button><button data-mini-delete="${r.id}">删除</button></div></article>`}
function renderMiniBase(){if(activeMini==='catalog'){document.title='生活小应用 · 回声';detail.innerHTML=`<section class="mini-hub-header"><div class="eyebrow">EVERYDAY, A LITTLE EASIER</div><h1>小工具，让生活有条理。</h1><p>学习、吃饭、出发和每一个普通日常，都可以从这里开始。</p><span class="mini-local-note">记录保存在当前浏览器，不会自动同步到其他设备。</span></section><div class="mini-app-grid">${miniApps.map(a=>`<button class="mini-app-tile ${a.color}" data-mini-app="${a.id}"><span class="mini-app-icon">${miniIcon(a.icon)}</span><span class="mini-app-tag">${a.tag}</span><h2>${a.name}</h2><p>${a.description}</p><span class="mini-app-footer">${miniData[a.id].length?miniData[a.id].length+' 条记录':'开始使用'} <span>↗</span></span></button>`).join('')}</div>`;return}const app=miniApps.find(a=>a.id===activeMini);if(!app){detail.innerHTML='<h2>未找到应用</h2><button data-mini-app="catalog">返回小应用</button>';return}document.title=app.name+' · 回声';const rows=miniVisible(app),total=rows.reduce((sum,r)=>sum+Math.round(Number(r.amount||0)*100),0)/100;const daily=['schedule','meals','habits'].includes(app.id);detail.innerHTML=`<button class="back-link" data-mini-app="catalog">← 全部小应用</button><section class="mini-tool-header"><div class="mini-app-icon">${miniIcon(app.icon)}</div><div><span class="mini-app-tag">${app.tag}</span><h1>${app.name}</h1><p>${app.description}</p></div></section><div class="mini-tool-toolbar"><div>${daily?`<label>查看日期 <input id="miniDate" type="date" value="${miniDate}" required></label><span class="mini-weekday">${miniWeekday(miniDate)}</span>`:app.id==='expenses'?`<label>查看月份 <input id="miniMonth" type="month" value="${miniMonth}" required></label>`:app.id==='travel'?`<label>旅行 <select id="miniTrip"><option value="all">全部旅行</option>${[...new Set(miniData.travel.map(r=>r.trip))].map(trip=>`<option value="${esc(trip)}" ${miniTrip===trip?'selected':''}>${esc(trip)}</option>`).join('')}</select></label>`:`<label>显示 <select id="miniTaskFilter"><option value="all" ${miniTaskFilter==='all'?'selected':''}>全部待办</option><option value="open" ${miniTaskFilter==='open'?'selected':''}>未完成</option><option value="done" ${miniTaskFilter==='done'?'selected':''}>已完成</option></select></label>`}</div><button class="primary" data-mini-add>＋ 添加记录</button></div>${app.id==='expenses'?`<section class="mini-budget-summary"><span>本月支出</span><strong>RM ${money(total)}</strong><div>${[...new Set(rows.map(r=>r.category))].map(category=>`<span>${esc(category)} <b>RM ${money(rows.filter(r=>r.category===category).reduce((n,r)=>n+Math.round(Number(r.amount)*100),0)/100)}</b></span>`).join('')}</div></section>`:app.id==='habits'?`<div class="mini-status-line">今日已完成 ${rows.filter(r=>(r.checks||[]).includes(miniDate)).length} / ${rows.length} 项</div>`:app.id==='tasks'?`<div class="mini-status-line">${miniData.tasks.filter(r=>!r.done).length} 项待完成</div>`:app.id==='schedule'?'<div class="mini-status-line">按星期循环显示，每周自动重复。</div>':''}${miniUndo?.app===app.id?'<div class="mini-undo">记录已删除。<button data-mini-undo>撤销删除</button></div>':''}<div class="mini-records">${rows.map(r=>miniRow(app,r)).join('')||`<div class="mini-empty">${miniIcon(app.icon)}<h3>这里还没有记录</h3><p>点「添加记录」，开始整理你的${app.name}。</p></div>`}</div><div class="mini-data-footer"><span>记录保存在当前浏览器</span><button data-mini-export>导出备份</button></div>`}
function miniEditor(id){const app=miniApps.find(a=>a.id===activeMini);if(!app)return;const existing=miniData[app.id].find(r=>r.id===id),r=existing||{date:app.id==='expenses'?miniMonth+'-01':miniDate,weekday:miniWeekday(miniDate),trip:miniTrip==='all'?'':miniTrip};open(`<div class="mini-label">${app.name}</div><h2>${existing?'编辑记录':'添加记录'}</h2><form id="miniRecordForm"><div class="mini-form-fields">${app.fields.map(([key,label,type,required,options])=>`<label>${label}${required?' *':''}${type==='select'?`<select name="${key}" ${required?'required':''}>${options.map(o=>`<option value="${o}" ${r[key]===o?'selected':''}>${o}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${key}" maxlength="2000">${esc(r[key]||'')}</textarea>`:`<input name="${key}" type="${type}" value="${esc(r[key]||'')}" ${required?'required':''} ${type==='number'?'min="0.01" max="999999999" step="0.01"':type==='text'?'maxlength="150"':''}>`}</label>`).join('')}</div><button type="submit" class="primary">保存记录</button></form>`);$('#miniRecordForm').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),record={...(existing||{id:crypto.randomUUID(),createdAt:Date.now(),done:false,checks:[]})};for(const [key,,type,required]of app.fields){record[key]=String(data.get(key)||'').trim();if(required&&!record[key]){toast('请填写必填项目');return}if(type==='number'&&(!Number.isFinite(Number(record[key]))||Number(record[key])<=0||Number(record[key])>999999999)){toast('请输入有效金额');return}}if(app.id==='schedule'&&record.end<=record.time){toast('结束时间必须晚于开始时间');return}if(app.id==='expenses')record.amount=Math.round(Number(record.amount)*100)/100;const before=miniData[app.id];miniData[app.id]=existing?before.map(r=>r.id===id?record:r):[...before,record];if(!saveMini()){miniData[app.id]=before;return}if(app.id==='meals')miniDate=record.date;if(app.id==='expenses')miniMonth=record.date.slice(0,7);if(app.id==='travel'&&miniTrip!=='all')miniTrip=record.trip;modal.close();renderMini();toast('记录已保存')}}
document.querySelector('.nav-main').insertAdjacentHTML('beforeend','<button data-mini-app="catalog">▦ <span>生活小应用</span></button>');
const miniMobile=document.querySelector('.mobile-nav [data-action="discover"]');if(miniMobile){miniMobile.removeAttribute('data-action');miniMobile.dataset.miniApp='catalog';miniMobile.innerHTML='▦<span>工具</span>'}
document.addEventListener('change',e=>{if(e.target.id==='miniDate'&&/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)){miniDate=e.target.value;renderMini()}if(e.target.id==='miniMonth'&&/^\d{4}-\d{2}$/.test(e.target.value)){miniMonth=e.target.value;renderMini()}if(e.target.id==='miniTrip'){miniTrip=e.target.value;renderMini()}if(e.target.id==='miniTaskFilter'){miniTaskFilter=e.target.value;renderMini()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.miniApp)openMini(d.miniApp);if('miniAdd'in d)miniEditor();if(d.miniEdit)miniEditor(d.miniEdit);const app=miniApps.find(a=>a.id===activeMini);if(!app)return;if(d.miniDelete){const row=miniData[app.id].find(r=>r.id===d.miniDelete);if(!row)return;const before=miniData[app.id];miniData[app.id]=before.filter(r=>r.id!==row.id);if(!saveMini()){miniData[app.id]=before;return}miniUndo={app:app.id,row};renderMini()}if('miniUndo'in d&&miniUndo?.app===app.id){miniData[app.id].push(miniUndo.row);if(!saveMini()){miniData[app.id].pop();return}miniUndo=null;renderMini()}if(d.miniToggle){const row=miniData[app.id].find(r=>r.id===d.miniToggle);if(!row)return;const before=JSON.stringify(row);if(app.id==='habits'){const checks=row.checks||[];row.checks=checks.includes(miniDate)?checks.filter(d=>d!==miniDate):[...checks,miniDate]}else row.done=!row.done;if(!saveMini())Object.assign(row,JSON.parse(before));renderMini()}if('miniExport'in d){const blob=new Blob([JSON.stringify({app:app.id,exportedAt:new Date().toISOString(),records:miniData[app.id]},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='echo-'+app.id+'-'+todayLocal()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});

// A single private overview connects existing records without duplicating them.
function personalOverview(){const today=todayLocal(),tasks=miniData.tasks.filter(r=>!r.done).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')),classes=miniData.schedule.filter(r=>r.weekday===miniWeekday(today)).sort((a,b)=>a.time.localeCompare(b.time)),trips=miniData.travel.filter(r=>r.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||'')),learning=courseCatalog.filter(c=>courseProgress(c)>0||Object.hasOwn(learningState.lastLesson,c.id)),myPosts=posts.filter(p=>p.user==='我').sort((a,b)=>b.createdAt-a.createdAt);return `<section class="overview-welcome"><div><div class="mini-label">YOUR DAY, IN ONE PLACE</div><h2>今天，从这里开始。</h2><p>${today} · ${miniWeekday(today)}</p></div><button class="primary" data-action="compose">＋ 分享一个想法</button></section><div class="overview-stats"><button data-mini-app="tasks"><strong>${tasks.length}</strong><span>待办事项</span></button><button data-mini-app="schedule"><strong>${classes.length}</strong><span>今日课程</span></button><button data-course="catalog"><strong>${learning.length}</strong><span>在学课程</span></button><button data-profile-tab="posts"><strong>${myPosts.length}</strong><span>我的帖子</span></button></div><div class="overview-grid"><section class="overview-panel"><div class="overview-panel-title"><h3>继续学习</h3><button data-course="catalog">全部课程 ↗</button></div>${learning.length?learning.slice(0,3).map(c=>`<button class="overview-course" data-resume-course="${c.id}"><img src="${COURSE_PHOTOS[c.id]}" alt=""><span><strong>${c.title}</strong><small>${courseProgress(c)} / ${c.lessons.length} 节已完成 · 继续学习 →</small></span></button>`).join(''):'<p class="overview-empty">还没有开始的课程。挑一门免费试看吧。</p>'}</section><section class="overview-panel"><div class="overview-panel-title"><h3>接下来要做</h3><button data-mini-app="tasks">全部待办 ↗</button></div>${tasks.length?tasks.slice(0,4).map(r=>`<button class="overview-row" data-mini-app="tasks"><strong>${esc(r.title)}</strong><small>${r.date?esc(r.date):'无截止日期'} · ${esc(r.priority)}${r.date&&r.date<today?' · 已逾期':''}</small></button>`).join(''):'<p class="overview-empty">暂时没有待办，给今天留一点空间。</p>'}</section><section class="overview-panel"><div class="overview-panel-title"><h3>今日课表</h3><button data-today-schedule>查看课表 ↗</button></div>${classes.length?classes.map(r=>`<button class="overview-row" data-today-schedule><strong>${esc(r.time)} · ${esc(r.title)}</strong><small>${esc(r.location||'地点待补充')}</small></button>`).join(''):'<p class="overview-empty">今天没有安排课程。</p>'}</section><section class="overview-panel"><div class="overview-panel-title"><h3>即将出发</h3><button data-mini-app="travel">旅行计划 ↗</button></div>${trips.length?trips.slice(0,3).map(r=>`<button class="overview-row" data-mini-app="travel"><strong>${esc(r.title)}</strong><small>${esc(r.trip)} · ${esc(r.date)} ${esc(r.time||'')}</small></button>`).join(''):'<p class="overview-empty">下一次出发，从一个旅行模板开始。</p>'}</section></div><section class="overview-panel"><div class="overview-panel-title"><h3>我的最新分享</h3><button data-profile-tab="posts">全部帖子 ↗</button></div>${myPosts.length?myPosts.slice(0,3).map(p=>`<button class="overview-row" data-post="${p.id}"><strong>${esc(p.title)}</strong><small>${relativeTime(p.createdAt)} · ${commentCount(p.comments)} 条评论</small></button>`).join(''):'<p class="overview-empty">记录一个发现，开启你的第一场讨论。</p>'}</section><p class="overview-private">个人总览仅汇集当前浏览器中的记录。</p>`}
function renderProfile(){renderProfileBase();if(activeProfile==='我'){const tabs=$('.profile-tabs');tabs?.insertAdjacentHTML('afterbegin',`<button data-profile-tab="overview" aria-pressed="${profileTab==='overview'}">我的总览</button>`);if(profileTab==='overview')$('.profile-content').innerHTML=personalOverview()}mountImageInputs()}
