function postAuthorHeader(post){const author=profileFor(post.user),c=community(post.c);return `<div class="post-author-header"><button class="post-author-main" data-author="${esc(post.user)}" aria-label="查看${esc(author.name)}的主页"><span class="post-author-avatar" style="background:${author.color}">${personAvatar(post.user)}</span><span class="post-author-text"><strong>${esc(author.name)}</strong><span>作者 · 查看主页 ↗</span></span></button><span class="post-author-time">${relativeTime(post.createdAt)}</span></div><div class="post-community-line">发布于 <button data-view="${c.id}">${c.icon} ${c.name}</button></div>`;}

function navigationSelected(data){
 if(activeMini!==null)return data.miniApp==='catalog';
 if(activeLearning!==null)return data.course==='catalog';
 if(activeProfile!==null)return activeProfile==='我'&&data.action==='profile';
 if(activePost!==null)return false;
 return !!data.view&&data.view===view;
}
function syncNavigation(){
 document.querySelectorAll('.nav-main button,.mobile-nav button,#communities button').forEach(button=>{
  const selected=navigationSelected(button.dataset);
  button.classList.toggle('active',selected);
  if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');
 });
}

