function translateLabel(value){if(translations[value])return translations[value];const patterns=[[/^(\d+) 分钟前$/,'$1m ago'],[/^(\d+) 小时前$/,'$1h ago'],[/^(\d+) 篇讨论$/,'$1 discussions'],[/^☏ (\d+) 条讨论$/,'☏ $1 comments'],[/^(\d+) 条评论( →)?$/,'$1 comments$2'],[/^(\d+) 赞同$/,'$1 upvotes'],[/^帖子 (\d+)$/,'Posts $1'],[/^回复 (\d+)$/,'Replies $1'],[/^↳ 回复 · (\d+)$/,'↳ Reply · $1'],[/^回复 (.+)$/,'Reply to $1'],[/^查看(.+)的主页$/,'View $1’s profile'],[/^展开 (.+) 的评论$/,'Expand $1’s comment'],[/^折叠 (.+) 的评论$/,'Collapse $1’s comment'],[/^([\d.k]+) 位同好( · 示例社区)?$/,'$1 members · Demo'],[/^示例 位同好( · 示例社区)?$/,'Demo community'],[/^篇帖子$/,'posts'],[/^条回复$/,'replies'],[/^位关注$/,'following'],[/^回复了$/,'Replied to']];for(const [r,s]of patterns)if(r.test(value))return value.replace(r,s);return value}
const originals=new WeakMap(),attributeOriginals=new WeakMap();
function protectedContent(element){return element?.closest('.feed-comment-text,.feed-comment-head,.post-title,.post p,.detail-body,.thread-comment p,.profile-bio,.profile-reply p,.profile-topics,.post-author-text strong,.profile-card h1,.author-link,.detail-card h1,textarea,script,style,#themeToggle,#languageToggle')}
function localize(){observer.disconnect();const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(protectedContent(node.parentElement))continue;let value=node.nodeValue;const cached=originals.get(node);if(cached&&value===cached.rendered)value=cached.original;const stripped=value.trim();const translated=preferences.language==='en'?translateLabel(stripped):stripped;const rendered=value.replace(stripped,translated);originals.set(node,{original:value,rendered});node.nodeValue=rendered}document.querySelectorAll('[placeholder],[aria-label],[title],[alt]').forEach(el=>{if(el.closest('.display-controls'))return;const memo=attributeOriginals.get(el)||{};for(const attr of ['placeholder','aria-label','title','alt']){if(!el.hasAttribute(attr))continue;let value=el.getAttribute(attr);if(memo[attr]&&value===memo[attr].rendered)value=memo[attr].original;const rendered=preferences.language==='en'?translateLabel(value):value;memo[attr]={original:value,rendered};el.setAttribute(attr,rendered)}attributeOriginals.set(el,memo)});document.documentElement.lang=preferences.language==='en'?'en':'zh-CN';observer.observe(document.body,{childList:true,subtree:true,characterData:true})}
const observer=new MutationObserver(localize);
function applyPreferences(){const dark=preferences.theme!=='light',english=preferences.language==='en';themeStyle.textContent=dark?NAVY_THEME:'';document.documentElement.dataset.theme=dark?'dark':'light';const themeButton=$('#themeToggle');themeButton.innerHTML=dark?sun:moon;themeButton.title=themeButton.ariaLabel=english?(dark?'Switch to light mode':'Switch to dark mode'):(dark?'切换浅色模式':'切换深色模式');themeButton.setAttribute('aria-pressed',String(dark));const languageButton=$('#languageToggle');languageButton.textContent=english?'中':'EN';languageButton.title=languageButton.ariaLabel=english?'切换到中文':'Switch to English';try{localStorage.setItem('huisheng-display',JSON.stringify(preferences))}catch{}localize()}
$('#themeToggle').onclick=()=>{preferences.theme=preferences.theme==='light'?'dark':'light';applyPreferences()};$('#languageToggle').onclick=()=>{preferences.language=preferences.language==='en'?'zh':'en';applyPreferences()};applyPreferences();

